<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/research-knowledge.php';
$u=require_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$project=project_access($pdo,(int)$u['id'],$id);if(!$project){http_response_code(404);exit('Research project not found.');}$canWrite=project_can_write($project);$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
    if(!$canWrite)throw new RuntimeException('You have view-only access to this project.');
    if($op==='create_claim'){
        $statement=trim((string)($_POST['statement']??''));if($statement==='')throw new RuntimeException('Claim statement is required.');
        $type=(string)($_POST['claim_type']??'factual');if(!in_array($type,['factual','disputed','prediction','interpretation','data_point'],true))$type='factual';
        $public=ulid_like();$pdo->prepare('INSERT INTO research_claims(public_id,project_id,created_by_user_id,statement,claim_type) VALUES(?,?,?,?,?)')->execute([$public,$project['id'],$u['id'],$statement,$type]);header('Location:/research-claim.php?id='.rawurlencode($public));exit;
    }
    if($op==='create_finding'){
        $title=trim((string)($_POST['title']??''));$summary=trim((string)($_POST['summary']??''));if($title===''||$summary==='')throw new RuntimeException('Finding title and summary are required.');
        $public=ulid_like();$pdo->prepare('INSERT INTO research_findings(public_id,project_id,created_by_user_id,title,summary) VALUES(?,?,?,?,?)')->execute([$public,$project['id'],$u['id'],$title,$summary]);header('Location:/research-finding.php?id='.rawurlencode($public));exit;
    }
}catch(Throwable $e){$error=$e->getMessage();}}
$q=$pdo->prepare("SELECT rc.*,u2.display_name,(SELECT COUNT(*) FROM claim_evidence ce WHERE ce.claim_id=rc.id) evidence_count FROM research_claims rc JOIN users u2 ON u2.id=rc.created_by_user_id WHERE rc.project_id=? ORDER BY FIELD(rc.status,'disputed','contradicted','unverified','supported','resolved'),rc.updated_at DESC");$q->execute([$project['id']]);$claims=$q->fetchAll();
$q=$pdo->prepare("SELECT rf.*,u2.display_name,(SELECT COUNT(*) FROM finding_claims fc WHERE fc.finding_id=rf.id) claim_count FROM research_findings rf JOIN users u2 ON u2.id=rf.created_by_user_id WHERE rf.project_id=? ORDER BY FIELD(rf.status,'draft','final','archived'),rf.updated_at DESC");$q->execute([$project['id']]);$findings=$q->fetchAll();
$claimCounts=array_fill_keys(['unverified','supported','disputed','contradicted','resolved'],0);foreach($claims as $c)$claimCounts[$c['status']]++;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Knowledge · <?=h($project['title'])?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/research-project.php?id=<?=h($project['public_id'])?>">Project</a><a href="/research.php">Research</a><a href="/search.php">Search</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">RESEARCH KNOWLEDGE · <?=h(strtoupper($project['access_role']))?></span><h1><?=h($project['title'])?></h1><p>Turn project evidence into structured Claims, then assemble Claims into Findings without losing Source-Version provenance.</p></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<div class="card"><div class="meta">CLAIM STATUS</div><p><?=count($claims)?> total · <?=h((string)$claimCounts['supported'])?> supported · <?=h((string)$claimCounts['disputed'])?> disputed · <?=h((string)$claimCounts['contradicted'])?> contradicted · <?=h((string)$claimCounts['unverified'])?> unverified</p></div>
<h2>Claims</h2><?php if(!$claims):?><div class="card empty">No Claims yet. Claims are structured statements that can carry supporting, contradicting, contextual, and primary evidence.</div><?php endif?><?php foreach($claims as $c):?><article class="card"><div class="meta"><?=h(strtoupper($c['claim_type']))?> · <?=h(strtoupper($c['status']))?> · <?=h((string)$c['evidence_count'])?> evidence · <?=h($c['display_name'])?></div><h3><a href="/research-claim.php?id=<?=h($c['public_id'])?>"><?=h($c['statement'])?></a></h3><?php if($c['resolution_note']):?><p><?=nl2br(h($c['resolution_note']))?></p><?php endif?></article><?php endforeach?>
<h2>Findings</h2><?php if(!$findings):?><div class="card empty">No Findings yet. Findings synthesize multiple Claims into a project-level conclusion.</div><?php endif?><?php foreach($findings as $f):?><article class="card"><div class="meta"><?=h(strtoupper($f['status']))?> · <?=h((string)$f['claim_count'])?> claims · <?=h($f['display_name'])?></div><h3><a href="/research-finding.php?id=<?=h($f['public_id'])?>"><?=h($f['title'])?></a></h3><p><?=nl2br(h(mb_substr((string)$f['summary'],0,600)))?></p></article><?php endforeach?></section><aside><?php if($canWrite):?><div class="card"><h3>New Claim</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="create_claim"><label>Statement<textarea name="statement" rows="5" required placeholder="State the claim precisely."></textarea></label><label>Type<select name="claim_type"><option value="factual">Factual</option><option value="disputed">Disputed</option><option value="prediction">Prediction</option><option value="interpretation">Interpretation</option><option value="data_point">Data point</option></select></label><button>Create Claim</button></form></div><div class="card"><h3>New Finding</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="create_finding"><label>Title<input name="title" required placeholder="Finding title"></label><label>Summary<textarea name="summary" rows="6" required placeholder="What does the assembled evidence show?"></textarea></label><button>Create Finding</button></form></div><?php endif?><div class="card"><h3>Knowledge model</h3><p class="meta">Source Version → Annotation → Claim → Evidence relationship → Finding. Project permissions apply to every object.</p></div></aside></main></body></html>
